<div id="supplier-modal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-black/50 p-4"><div class="max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded bg-white shadow-2xl"><div class="sticky top-0 z-10 flex items-center justify-between border-b border-outline-variant/30 bg-white px-5 py-4"><div><p class="text-xs font-semibold uppercase tracking-wider text-primary">Supplier Manager</p><h2 id="supplier-modal-title" class="mt-1 text-lg font-semibold">Add Supplier</h2></div><button id="close-supplier-modal" type="button" class="rounded p-2 hover:bg-primary hover:text-white"><span class="material-symbols-outlined">close</span></button></div><form id="supplier-form" method="POST" action="{{ route('suppliers.store') }}" class="grid grid-cols-1 gap-4 p-5 md:grid-cols-2">@csrf<input id="supplier-method" type="hidden" name="_method" value="POST"><label class="text-xs font-semibold text-on-surface-variant">Business Name <span class="text-error">*</span><input id="business-name" required name="business_name" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm font-normal outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">Salutation<select id="owner-salutation" name="owner_salutation" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm font-normal outline-none focus:border-primary"><option value="">Select (optional)</option><option value="Mr.">Mr.</option><option value="Mrs.">Mrs.</option><option value="Atty.">Atty.</option></select></label><div class="md:col-span-2"><p class="text-xs font-semibold text-on-surface-variant">Business Owner Name</p><div class="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-3"><input id="owner-given-name" name="owner_given_name" placeholder="Given Name" class="rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"><input id="owner-middle-initial" name="owner_middle_initial" placeholder="Middle Initial (Optional)" class="rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"><input id="owner-last-name" name="owner_last_name" placeholder="Last Name" class="rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></div></div><label class="text-xs font-semibold text-on-surface-variant md:col-span-2">Business Address<textarea id="business-address" name="business_address" rows="2" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></textarea></label><label class="text-xs font-semibold text-on-surface-variant">Contact Person<input id="contact-person" name="contact_person" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">Phone / Mobile<input id="phone" name="phone" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">Email<input id="email" type="email" name="email" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">TIN<input id="tin" name="tin" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">Business Permit No.<input id="business-permit" name="business_permit_no" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">PhilGEPS Registration No.<input id="philgeps" name="philgeps_no" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></label><label class="text-xs font-semibold text-on-surface-variant">Status<select id="status" name="status" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label class="text-xs font-semibold text-on-surface-variant md:col-span-2">Notes<textarea id="notes" name="notes" rows="3" placeholder="Accreditation notes, product categories, or other details" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm outline-none focus:border-primary"></textarea></label><div class="flex justify-end gap-2 border-t border-outline-variant/30 pt-4 md:col-span-2"><button id="cancel-supplier-modal" type="button" class="rounded border border-outline-variant/50 px-4 py-2.5 text-xs font-semibold hover:bg-primary hover:text-white">Cancel</button><button type="submit" class="rounded bg-primary px-4 py-2.5 text-xs font-semibold text-white hover:bg-primary-container">Save Supplier</button></div></form></div></div>
<script>
const modal=document.getElementById('supplier-modal'),form=document.getElementById('supplier-form'),sidebar=document.getElementById('supplier-sidebar'),overlay=document.getElementById('supplier-menu-overlay');
const supplierAddressees=@json($suppliers->pluck('addressee', 'id'));
document.getElementById('business-name').closest('label').insertAdjacentHTML('afterend','<label class="text-xs font-semibold text-on-surface-variant">Addressee<input id="addressee" name="addressee" placeholder="e.g. The Manager" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm font-normal outline-none focus:border-primary"></label>');
const closeModal=()=>{modal.classList.add('hidden');modal.classList.remove('flex');}; const setValue=(id,value)=>{document.getElementById(id).value=value||'';}; const ids=['business-name','addressee','owner-salutation','owner-given-name','owner-middle-initial','owner-last-name','business-address','contact-person','phone','email','tin','business-permit','philgeps','notes'];
const openSidebar=()=>{sidebar.classList.remove('-translate-x-full');overlay.classList.remove('hidden');};const closeSidebar=()=>{sidebar.classList.add('-translate-x-full');overlay.classList.add('hidden');};
document.getElementById('open-supplier-menu').addEventListener('click',openSidebar);overlay.addEventListener('click',closeSidebar);
document.getElementById('add-supplier').addEventListener('click',()=>{form.action=@json(route('suppliers.store'));document.getElementById('supplier-method').value='POST';document.getElementById('supplier-modal-title').textContent='Add Supplier';ids.forEach(id=>setValue(id,''));setValue('status','active');modal.classList.remove('hidden');modal.classList.add('flex');});
document.querySelectorAll('[data-edit-supplier]').forEach(button=>button.addEventListener('click',()=>{form.action=`{{ url('/procurement/suppliers') }}/${button.dataset.supplier}`;document.getElementById('supplier-method').value='PUT';document.getElementById('supplier-modal-title').textContent='Edit Supplier';setValue('business-name',button.dataset.businessName);setValue('addressee',supplierAddressees[button.dataset.supplier]);setValue('owner-salutation',button.dataset.ownerSalutation);setValue('owner-given-name',button.dataset.ownerGivenName);setValue('owner-middle-initial',button.dataset.ownerMiddleInitial);setValue('owner-last-name',button.dataset.ownerLastName);setValue('business-address',button.dataset.businessAddress);setValue('contact-person',button.dataset.contactPerson);setValue('phone',button.dataset.phone);setValue('email',button.dataset.email);setValue('tin',button.dataset.tin);setValue('business-permit',button.dataset.businessPermit);setValue('philgeps',button.dataset.philgeps);setValue('notes',button.dataset.notes);setValue('status',button.dataset.status);modal.classList.remove('hidden');modal.classList.add('flex');}));
document.getElementById('close-supplier-modal').addEventListener('click',closeModal);document.getElementById('cancel-supplier-modal').addEventListener('click',closeModal);modal.addEventListener('click',event=>{if(event.target===modal)closeModal();});document.getElementById('supplier-search').addEventListener('input',event=>{const query=event.target.value.toLowerCase();document.querySelectorAll('[data-supplier-row]').forEach(row=>row.classList.toggle('hidden',!row.dataset.search.includes(query)));});
</script>
<script>
    (() => {
        const addressee = document.getElementById('addressee');
        const salutation = document.getElementById('owner-salutation');
        const givenName = document.getElementById('owner-given-name');
        const middleInitial = document.getElementById('owner-middle-initial');
        const lastName = document.getElementById('owner-last-name');
        const ownerPanel = givenName.closest('.md\\:col-span-2');
        const ownerGrid = givenName.parentElement;
        const supplierDetails = @json($suppliers->mapWithKeys(fn ($supplier) => [$supplier->id => ['type' => $supplier->tax_type ?? 'non_vat', 'rate' => $supplier->tax_rate ?? 0, 'hasOwner' => (bool) $supplier->has_company_owner]]));

        salutation.closest('label').remove();
        ownerGrid.className = 'mt-2 grid grid-cols-1 gap-3 sm:grid-cols-4';
        const makeOwnerField = (label, input) => {
            const field = document.createElement('label');
            field.className = 'text-xs font-medium text-on-surface-variant';
            field.textContent = label;
            input.classList.add('mt-1', 'w-full');
            input.remove();
            ownerGrid.appendChild(field);
            field.appendChild(input);
        };
        makeOwnerField('Salutation', salutation);
        makeOwnerField('Given Name', givenName);
        makeOwnerField('Middle Initial', middleInitial);
        makeOwnerField('Last Name', lastName);
        const ownerTitle = ownerPanel.querySelector('p');
        ownerTitle.insertAdjacentHTML('afterend', '<div class="mt-3 flex flex-wrap gap-4 text-xs font-medium text-on-surface-variant"><label class="flex items-center gap-2"><input id="has-company-owner" type="checkbox" name="has_company_owner" value="1" class="rounded border-outline-variant/50 text-primary focus:ring-primary">Show company owner details</label><label id="owner-addressee-option" class="flex items-center gap-2"><input id="use-owner-as-addressee" type="checkbox" class="rounded border-outline-variant/50 text-primary focus:ring-primary">Use salutation and last name as letter addressee</label></div>');
        const useOwnerAsAddressee = document.getElementById('use-owner-as-addressee');
        const hasCompanyOwner = document.getElementById('has-company-owner');
        const ownerAddresseeOption = document.getElementById('owner-addressee-option');
        const ownerInputs = [salutation, givenName, middleInitial, lastName];
        const toggleOwnerFields = () => {
            const visible = hasCompanyOwner.checked;
            ownerTitle.classList.toggle('hidden', !visible);
            ownerGrid.classList.toggle('hidden', !visible);
            ownerAddresseeOption.classList.toggle('hidden', !visible);
            ownerInputs.forEach((field) => { field.disabled = !visible; });
            if (!visible) useOwnerAsAddressee.checked = false;
        };
        const updateAddressee = () => {
            if (useOwnerAsAddressee.checked) addressee.value = [salutation.value, lastName.value].filter(Boolean).join(' ');
        };
        [salutation, lastName].forEach((field) => field.addEventListener('input', updateAddressee));
        useOwnerAsAddressee.addEventListener('change', updateAddressee);
        hasCompanyOwner.addEventListener('change', toggleOwnerFields);

        const tin = document.getElementById('tin');
        tin.closest('label').insertAdjacentHTML('afterend', '<label class="text-xs font-semibold text-on-surface-variant">Tax Type<select id="tax-type" name="tax_type" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm font-normal outline-none focus:border-primary"><option value="">Select tax type</option><option value="vat">VAT</option><option value="non_vat">Non-VAT</option><option value="vat_exempt">VAT Exempt</option></select></label><label class="text-xs font-semibold text-on-surface-variant">Tax Rate (%) <span class="font-normal">(optional)</span><input id="tax-rate" type="number" min="0" max="100" step="0.01" name="tax_rate" placeholder="Enter applicable rate" class="mt-2 w-full rounded border border-outline-variant/50 bg-surface-low px-3 py-2.5 text-sm font-normal outline-none focus:border-primary"></label>');
        const taxType = document.getElementById('tax-type');
        const taxRate = document.getElementById('tax-rate');
        taxRate.closest('label').insertAdjacentHTML('afterend', '<div class="rounded border border-primary/20 bg-primary/5 p-3 text-xs text-on-surface-variant md:col-span-2"><p class="font-semibold text-primary">Tax computation preview</p><div class="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-3"><label>Taxable Amount<input id="tax-preview-amount" type="number" min="0" step="0.01" placeholder="Enter amount" class="mt-1 w-full rounded border border-outline-variant/50 bg-white px-3 py-2 text-sm outline-none focus:border-primary"></label><div><p>Tax Amount</p><p id="tax-preview-tax" class="mt-2 font-semibold text-on-surface">₱0.00</p></div><div><p>Total Including Tax</p><p id="tax-preview-total" class="mt-2 font-semibold text-primary">₱0.00</p></div></div><p id="tax-preview-formula" class="mt-3">Enter the applicable tax rate and taxable amount to calculate.</p></div>');
        const taxPreviewAmount = document.getElementById('tax-preview-amount');
        const updateTaxPreview = () => {
            const amount = Number(taxPreviewAmount.value) || 0;
            const rate = Number(taxRate.value) || 0;
            const tax = amount * (rate / 100);
            const money = (value) => `₱${value.toLocaleString('en-PH', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
            document.getElementById('tax-preview-tax').textContent = money(tax);
            document.getElementById('tax-preview-total').textContent = money(amount + tax);
            const taxLabel = taxType.value === 'vat' ? 'VAT' : taxType.value === 'non_vat' ? 'Non-VAT tax' : taxType.value === 'vat_exempt' ? 'VAT Exempt' : 'Tax';
            document.getElementById('tax-preview-formula').textContent = `${taxLabel}: ${money(amount)} × ${rate}% = ${money(tax)}`;
        };
        [taxType, taxRate, taxPreviewAmount].forEach((field) => field.addEventListener('input', updateTaxPreview));
        taxType.addEventListener('change', updateTaxPreview);
        document.getElementById('add-supplier').addEventListener('click', () => { taxType.value = ''; taxRate.value = ''; taxPreviewAmount.value = ''; updateTaxPreview(); useOwnerAsAddressee.checked = false; hasCompanyOwner.checked = false; toggleOwnerFields(); });
        document.querySelectorAll('[data-edit-supplier]').forEach((button) => button.addEventListener('click', () => {
            const details = supplierDetails[button.dataset.supplier] || {type: '', rate: '', hasOwner: false};
            taxType.value = details.type;
            taxRate.value = details.rate;
            taxPreviewAmount.value = '';
            updateTaxPreview();
            useOwnerAsAddressee.checked = false;
            hasCompanyOwner.checked = details.hasOwner;
            toggleOwnerFields();
        }));
        toggleOwnerFields();
    })();
</script>@include('partials.profile-menu')</body></html>
